public static int findNthLeapYear(int Y, int N) {
    if (N <= 0) {
        throw new IllegalArgumentException("N must be a positive integer.");
    }
    int count = 0;
    while (true) {
        if (isLeapYear(Y)) {
            count++;
            if (count == N) {
                return Y;
            }
        }
        Y++;
    }
}

private static boolean isLeapYear(int year) {
    return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
}
