public int findLargestSubstring(List<String> strings) {
    int maxLength = 0;

    // Iterate through each pair of strings
    for (int i = 0; i < strings.size(); i++) {
        for (int j = i + 1; j < strings.size(); j++) {
            String s1 = strings.get(i);
            String s2 = strings.get(j);

            // Check if s1 or its reverse is a substring of s2
            if (s2.contains(s1) || s2.contains(new StringBuilder(s1).reverse().toString())) {
                maxLength = Math.max(maxLength, s1.length());
            }

            // Check if s2 or its reverse is a substring of s1
            if (s1.contains(s2) || s1.contains(new StringBuilder(s2).reverse().toString())) {
                maxLength = Math.max(maxLength, s2.length());
            }
        }
    }

    return maxLength;
}
