public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    Set<String> words = new HashSet<>(strings);
    int maxLen = 0;

    for (String str : words) {
        if (containsInverseOrSelf(words, str)) {
            maxLen = Math.max(maxLen, str.length());
        }
    }

    return maxLen;
}

private boolean containsInverseOrSelf(Set<String> words, String str) {
    StringBuilder inverse = new StringBuilder(str).reverse();
    for (String word : words) {
        if (word.contains(str) || word.contains(inverse.toString())) {
            return true;
        }
    }
    return false;
}
