public static int maxRegions(int N) {
    if (N < 1) {
        return 1; // No triangles, the plane remains as one region
    }
    int regions = 1; // Start with one region (the whole plane)
    for (int i = 1; i <= N; i++) {
        regions += i * (i + 1) / 2; // Increment regions based on the number of triangles
    }
    return regions;
}
