public class RegionCounter {

    /**
     * Calculates the maximum number of regions a plane can be divided into by N triangles.
     *
     * @param N the number of triangles
     * @return the maximum number of regions
     */
    public static int maxRegions(int N) {
        if (N < 0) {
            throw new IllegalArgumentException("Number of triangles must be non-negative.");
        }
        // The formula to calculate the maximum number of regions is (N * (N + 1)) / 2 + 1
        return (N * (N + 1)) / 2 + 1;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(maxRegions(1)); // Should print 2
        System.out.println(maxRegions(2)); // Should print 8
        System.out.println(maxRegions(3)); // Should print 17
        System.out.println(maxRegions(4)); // Should print 31
        System.out.println(maxRegions(0)); // Should print 1
    }
}
