public static int maxRegions(int N) {
    // Base case: if there are no triangles, the plane is undivided
    if (N == 0) {
        return 1;
    }

    // Initialize the number of regions with the base case
    int regions = 1;

    // Each new triangle can intersect with all previous triangles, creating new regions
    for (int i = 1; i <= N; i++) {
        // Each triangle can intersect with all previous triangles, adding (number of previous triangles + 1) new regions
        regions += i + 1;
    }

    return regions;
}
