import java.util.*;

public class MazeSolver {
    public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
        List<int[]> graph = new ArrayList<>();
        for (int[] path : paths) {
            graph.add(path);
        }

        Queue<int[]> queue = new LinkedList<>();
        Set<String> visited = new HashSet<>();
        queue.add(start);
        visited.add(start[0] + "," + start[1]);

        while (!queue.isEmpty()) {
            int[] current = queue.poll();
            int currentX = current[0];
            int currentY = current[1];

            if (currentX == end[0] && currentY == end[1]) {
                return "can be travelled";
            }

            int[][] directions = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
            for (int[] direction : directions) {
                int newX = currentX + direction[0];
                int newY = currentY + direction[1];
                if (newX >= 0 && newX < n && newY >= 0 && newY < n) {
                    int[] next = {newX, newY};
                    if (!visited.contains(newX + "," + newY)) {
                        boolean isPath = false;
                        for (int[] path : graph) {
                            if ((path[0] == currentX && path[1] == currentY && path[2] == newX && path[3] == newY) ||
                                (path[0] == newX && path[1] == newY && path[2] == currentX && path[3] == currentY)) {
                                isPath = true;
                                break;
                            }
                        }
                        if (isPath) {
                            queue.add(next);
                            visited.add(newX + "," + newY);
                        }
                    }
                }
            }
        }

        return "cannot be travelled";
    }
}
