public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    int startX = start[0];
    int startY = start[1];
    int endX = end[0];
    int endY = end[1];

    // Create a 2D array to represent the maze
    boolean[][] maze = new boolean[n][n];
    for (int[] path : paths) {
        int x1 = path[0];
        int y1 = path[1];
        int x2 = path[2];
        int y2 = path[3];
        maze[x1][y1] = true;
        maze[x2][y2] = true;
    }

    // Check if the start and end positions are valid
    if (!maze[startX][startY] || !maze[endX][endY]) {
        return "cannot be travelled";
    }

    // Create a 2D array to keep track of visited positions
    boolean[][] visited = new boolean[n][n];
    visited[startX][startY] = true;

    // Use a queue for BFS
    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{startX, startY});

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        // Check if we have reached the end position
        if (x == endX && y == endY) {
            return "can be travelled";
        }

        // Explore the neighbors
        int[] directions = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] direction : directions) {
            int newX = x + direction[0];
            int newY = y + direction[1];

            // Check if the new position is within the maze boundaries and not visited
            if (newX >= 0 && newX < n && newY >= 0 && newY < n && !visited[newX][newY] && maze[newX][newY]) {
                visited[newX][newY] = true;
                queue.add(new int[]{newX, newY});
            }
        }
    }

    // If we exhaust the queue without finding the end position, return "cannot be travelled"
    return "cannot be travelled";
}
