public class ApproximateValueCalculator {

    /**
     * Calculates the approximate value by counting the number of common letters
     * and dividing it by the sum of the lengths of the two words.
     *
     * @param word1 The first word.
     * @param word2 The second word.
     * @return The approximate value as a reduced fraction.
     */
    public static String appx(String word1, String word2) {
        Set<Character> set1 = new HashSet<>();
        Set<Character> set2 = new HashSet<>();

        // Add characters of word1 to set1
        for (char c : word1.toCharArray()) {
            set1.add(c);
        }

        // Add characters of word2 to set2
        for (char c : word2.toCharArray()) {
            set2.add(c);
        }

        // Find common characters
        set1.retainAll(set2);
        int commonLetters = set1.size();

        // Calculate the sum of the lengths of the two words
        int totalLength = word1.length() + word2.length();

        // Reduce the fraction
        int gcd = gcd(commonLetters, totalLength);
        commonLetters /= gcd;
        totalLength /= gcd;

        // Return the result as a reduced fraction
        return String.format("appx(%s, %s) = %d/%d", word1, word2, commonLetters, totalLength);
    }

    /**
     * Calculates the greatest common divisor (GCD) of two integers.
     *
     * @param a First integer.
     * @param b Second integer.
     * @return The GCD of the two integers.
     */
    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    // Test cases
    public static void main(String[] args) {
