import java.util.HashMap;

public class PairSumDivisibility {

    /**
     * Checks if it is possible to divide the array into n/2 pairs such that the sum of each pair is divisible by k.
     *
     * @param arr the input integer array
     * @param k the divisor
     * @return true if it is possible, false otherwise
     */
    public static boolean canArrange(int[] arr, int k) {
        if (arr.length % 2 != 0) {
            return false;
        }

        HashMap<Integer, Integer> remainderCounts = new HashMap<>();

        // Calculate the remainders when each element is divided by k
        for (int num : arr) {
            int remainder = (num % k + k) % k; // Ensuring positive remainder
            remainderCounts.put(remainder, remainderCounts.getOrDefault(remainder, 0) + 1);
        }

        // Check pairs of remainders
        for (Map.Entry<Integer, Integer> entry : remainderCounts.entrySet()) {
            int remainder = entry.getKey();
            int count = entry.getValue();

            if ((remainder == 0 && count % 2 != 0) || (remainder * 2 != k && !remainderCounts.containsKey(k - remainder) || !remainderCounts.get(k - remainder).equals(count))) {
                return false;
            }
        }

        return true;
    }

    public static void main(String[] args) {
        // Test cases
        int[] arr1 = {1, 2, 3, 4, 5, 10, 6, 7, 8, 9};
        int k1 = 5;
        System.out.println(canArrange(arr1, k1)); // Output: true

        int[] arr2 = {1, 2, 3, 4, 5, 6};
        int k2 = 7;
        System.out.println(canArrange(arr2, k2)); // Output: true

        int[] arr3 = {1, 2, 3, 4, 5, 6};
        int k3 = 10;
        System.out.println(canArrange(arr3, k3)); // Output: false
    }
}
