        List<List<Integer>> adjList = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adjList.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            adjList.get(edge[0]).add(edge[1]);
            adjList.get(edge[1]).add(edge[0]);
        }
        return dfs(0, -1, adjList, hasApple) * 2;
    }

    private int dfs(int node, int parent, List<List<Integer>> adjList, boolean[] hasApple) {
        int time = 0;
        for (int neighbor : adjList.get(node)) {
            if (neighbor == parent) {
                continue;
            }
            time += dfs(neighbor, node, adjList, hasApple);
        }
        if ((node != 0 || !adjList.get(node).isEmpty()) && (time > 0 || hasApple[node])) {
            time += 2;
        }
        return time;
    }
}
