public class Solution {
    Map<Integer, List<Integer>> adjList;
    boolean[] hasApple;

    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        this.adjList = new HashMap<>();
        this.hasApple = hasApple;

        // Build the adjacency list
        for (int i = 0; i < n; i++) {
            adjList.put(i, new ArrayList<>());
        }
        for (int[] edge : edges) {
            adjList.get(edge[0]).add(edge[1]);
            adjList.get(edge[1]).add(edge[0]);
        }

        // Calculate the minimum time required
        return dfs(0, -1) * 2;
    }

    private int dfs(int node, int parent) {
        int totalTime = 0;
        for (int neighbor : adjList.get(node)) {
            if (neighbor == parent) continue; // Avoid revisiting the parent node
            int childTime = dfs(neighbor, node);
            if (childTime > 0 || hasApple[neighbor]) {
                totalTime += childTime + 2; // Each valid path contributes 2 units of time
            }
        }
        return totalTime;
    }

