public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }

    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    for (int i = 1; i <= n / 2; i++) {
        Set<Double> set = new HashSet<>();
        int target = n - i;
        boolean possible = recurse(nums, sum, i, target, 0, 0, set);
        if (possible) {
            return true;
        }
    }

    return false;
}

private boolean recurse(int[] nums, int sum, int i, int target, int index, int currentSum, Set<Double> set) {
    if (i == 0) {
        return target == 0 && currentSum == 0;
    }

    boolean result = false;

    if (currentSum + nums[index] <= sum) {
        result = recurse(nums, sum, i - 1, target - 1, index + 1, currentSum + nums[index], set);
    }
    result = result || recurse(nums, sum, i, target, index + 1, currentSum, set);

    return result;
}
