public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }

    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[] dp = new boolean[sum + 1];
    dp[0] = true;

    for (int num : nums) {
        for (int j = sum; j >= num; j--) {
            dp[j] = dp[j] || dp[j - num];
        }
    }

    int minSize = n / 2;
    for (int i = 1; i <= minSize; i++) {
        if (sum * i % n == 0 && dp[sum * i / n]) {
            return true;
