public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    int sum = Arrays.stream(nums).sum();

    // Check if any subset has an average equal to the overall average
    for (int k = 1; k < n; k++) {
        if ((sum * k) % n == 0) {
            Set<Integer> subsetSums = new HashSet<>();
            subsetSums.add(0);
            int partialSum = 0;
            for (int j = 0; j < n; j++) {
                partialSum += nums[j];
                if (subsetSums.contains(partialSum - (sum * k / n))) {
                    return true;
                }
                subsetSums.add(partialSum);
            }
        }
    }
    return false;
}
