public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[][] possible = new boolean[n + 1][sum + 1];

    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= sum; j++) {
            if (i == 0 || j == 0) {
                possible[i][j] = i == 0 && j == 0 ? true : false;
            } else {
                if (nums[n - i] <= j) {
                    possible[i][j] = possible[i - 1][j] || possible[i - 1][j - nums[n - i]];
                } else {
                    possible[i][j] = possible[i - 1][j];
                }
            }
        }
    }

    for (int i = 1; i < n; i++) {
        for (int j = 1; j <= sum; j++) {
            if (possible[i][j] && (sum * i) % n == (sum * (n - i)) % n && j * n == sum * i) {
                return true;
            }
        }
    }

    return false;
}
