public boolean hasAllCodes(String s, int k) {
    if (s.length() < Math.pow(2, k)) {
        return false;
    }

    boolean[] seen = new boolean[1 << k];
    int count = 0;
    int value = 0;

    for (int i = 0; i < s.length(); i++) {
        value = (value << 1) & ((1 << k) - 1);
        value |= s.charAt(i) - '0';

        if (i >= k - 1) {
            if (!seen[value]) {
                seen[value] = true;
                count++;
            }
        }
    }

    return count == (1 << k);
}
