import java.util.*;

public class Solution {

    /**
     * Finds the minimum number of Fibonacci numbers whose sum is equal to k.
     *
     * @param k the target sum
     * @return the minimum number of Fibonacci numbers whose sum is equal to k
     */
    public int findMinFibonacciNumbers(int k) {
        List<Integer> fibNumbers = new ArrayList<>();
        int a = 1;
        int b = 1;
        fibNumbers.add(a);
        fibNumbers.add(b);

        // Generate Fibonacci numbers up to the largest number <= k
        while (true) {
            int next = a + b;
            if (next > k) break;
            fibNumbers.add(next);
            a = b;
            b = next;
        }

        int minCount = Integer.MAX_VALUE;
        // Use a greedy approach to find the minimum number of Fibonacci numbers
        for (int i = fibNumbers.size() - 1; i >= 0; i--) {
            if (i == 0) {
                minCount = Math.min(minCount, 1);
                break;
            }

            int count = 0;
            int sum = 0;
            int idx = i;
            while (sum < k) {
                sum += fibNumbers.get(idx);
                count++;
                if (sum == k) {
                    minCount = Math.min(minCount, count);
                    break;
                }
                idx = Collections.binarySearch(fibNumbers, k - sum);
                if (idx < 0) idx = -idx - 2;
            }
        }

        return minCount;
    }
}
