public String getSmallestString(int n, int k) {
    StringBuilder result = new StringBuilder();
    int remaining = k;

    for (int i = 1; i <= n; i++) {
        if (remaining == i) {
            result.append((char) ('a' + i - 1));
        } else if (remaining < i) {
            result.append((char) ('a' + remaining - 1));
        } else {
            result.append('a');
            remaining -= 1;
            int diff = n - i;
            if (remaining >= diff * 26) {
                result.append('z');
                remaining -= 26;
            } else {
                char c = (char) ('a' + (remaining - 1) / diff);
                result.append(c);
                remaining -= (c - 'a' + 1) * diff;
            }
        }
    }

    return result.toString();
}
