public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    Arrays.fill(result, 'a'); // Initialize the result array with 'a'
    k -= n; // Subtract n because each 'a' contributes 1 to the value

    int index = n - 1;
    while (k > 0) {
        int add = Math.min(25, k); // We can add at most 25 to get to 'z'
        result[index] += add; // Increment the current character
        k -= add; // Reduce k by the amount added
        index--; // Move to the previous character
    }

    return new String(result);
}
