        List<Integer> result = new ArrayList<>();
        if (low > high) {
            return result;
        }

        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i <= 9; i++) {
            if (i >= low && i <= high) {
                result.add(i);
            }
            if (i > 0) {
                queue.offer(i);
            }
        }

        while (!queue.isEmpty()) {
            int num = queue.poll();
            if (num > high) {
                continue;
            }
            int lastDigit = num % 10;
            if (lastDigit + 1 <= 9 && (num * 10 + lastDigit + 1) <= high) {
                result.add(num * 10 + lastDigit + 1);
                queue.offer(num * 10 + lastDigit + 1);
            }
            if (lastDigit - 1 >= 0 && (num * 10 + lastDigit - 1) <= high) {
                result.add(num * 10 + lastDigit - 1);
                queue.offer(num * 10 + lastDigit - 1);
            }
        }

        Collections.sort(result);
        return result;
    }

