public static int countDigitOne(int n) {
    if (n < 1) {
        return 0;
    }

    int count = 0;
    long factor = 1;
    long cur = n % 10;
    long low = n - n % 10;
    long high = n / 10;

    while (high != 0 || cur != 0) {
        if (cur == 0) {
            count += high * factor;
        } else if (cur == 1) {
            count += high * factor + low + 1;
        } else {
            count += (high + 1) * factor;
        }

        low += cur * factor;
        cur = high % 10;
        high /= 10;
        factor *= 10;
    }

    return count;
}
