        long level = n / (factor * 10);
        long current = (n / factor) % 10;
        long rest = n % factor;

        if (current == 0) {
            count += level * factor;
        } else if (current == 1) {
            count += level * factor + rest + 1;
        } else {
            count += (level + 1) * factor;
        }
    }

    return count;
}
