public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    // Arrays to store the counts of consecutive 1s
    int[][][] dp = new int[4][rows][cols]; // 0: Horizontal, 1: Vertical, 2: Diagonal, 3: Anti-diagonal

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (mat[r][c] == 0) continue;

            // Horizontal
            dp[0][r][c] = (c > 0) ? dp[0][r][c - 1] + 1 : 1;

            // Vertical
            dp[1][r][c] = (r > 0) ? dp[1][r - 1][c] + 1 : 1;

            // Diagonal
            dp[2][r][c] = ((r > 0) && (c > 0)) ? dp[2][r - 1][c - 1] + 1 : 1;

            // Anti-diagonal
            dp[3][r][c] = ((r > 0) && (c < cols - 1)) ? dp[3][r - 1][c + 1] + 1 : 1;

            // Update the maximum length
            maxLength = Math.max(maxLength, dp[0][r][c]);
            maxLength = Math.max(maxLength, dp[1][r][c]);
            maxLength = Math.max(maxLength, dp[2][r][c]);
            maxLength = Math.max(maxLength, dp[3][r][c]);
        }
    }

    return maxLength;
}
