        return 0;
    }

    return backtrack(A, 0, new HashMap<>());
}

private static int backtrack(int[] A, int index, Map<Integer, List<List<Integer>>> memo) {
    int n = A.length;
    if (index == n - 1) {
        return 1;
    }

    if (memo.containsKey(index)) {
        return memo.get(index).stream().mapToInt(list -> backtrack(A, index + list.size(), memo)).sum();
    }

    int count = 0;
    for (int i = index + 1; i < n; i++) {
        int diff = A[i] - A[index];
        int root = (int) Math.sqrt(diff);
        if (root * root == diff) {
            List<Integer> next = new ArrayList<>();
            next.add(A[i]);
            List<List<Integer>> results = memo.getOrDefault(index, new ArrayList<>());
            results.add(next);
            memo.put(index, results);
            count += backtrack(A, i + 1, memo);
        }
    }

    memo.put(index, new ArrayList<>());
    return count;
}
