private static int backtrack(int[] A, int start, boolean[] used) {
    if (start == A.length - 1) return 1;

    int count = 0;
    for (int i = start; i < A.length; i++) {
        if (used[i] || (start > 0 && !isPerfectSquare(A[start - 1] + A[i]))) continue;
        used[i] = true;
        count += backtrack(A, start + 1, used);
        used[i] = false;
    }

    return count;
