import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        int n = A.length;
        if (n == 0) return 0;

        Set<Integer> ps = new HashSet<>();
        for (int i = 0; i < A[0] * A[0]; i++) {
            ps.add(i);
        }

        return permute(A, 1, ps, 0);
    }

    private static int permute(int[] A, int index, Set<Integer> ps, int count) {
        if (index == A.length) {
            return count + 1;
        }

        Set<Integer> newPs = new HashSet<>();
        for (int i = 0; i < A[index] * A[index]; i++) {
            if (i + A[index - 1] >= A[index] * A[index] || !ps.contains(i + A[index - 1])) continue;
            newPs.add(i);
        }

        int result = 0;
        for (int num : newPs) {
            A[index] = num;
            result += permute(A, index + 1, newPs, count);
        }

        return result;
    }

    public static void main(String[] args) {
        System.out.println(squarePermutations(new int[]{1, 17, 8})); // Output: 2
        System.out.println(squarePermutations(new int[]{2, 2, 2})); // Output: 1
    }
}
