    if (A == null || A.length == 0) {
        return 0;
    }

    int N = A.length;
    int count = 0;
    boolean[] used = new boolean[N];
    helper(A, used, 0, count);
    return count;
}

private static void helper(int[] A, boolean[] used, int index, int count) {
    if (index == A.length - 1) {
        count++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (!used[i]) {
            int sum = A[index] + A[i];
            if (isPerfectSquare(sum)) {
                used[i] = true;
                helper(A, used, index + 1, count);
                used[i] = false;
            }
        }
    }
}

private static boolean isPerfectSquare(int num) {
    int sqrt = (int) Math.sqrt(num);
    return sqrt * sqrt == num;
}
