    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;

    boolean goingUp = true;

    for (int i = 0; i < m + n - 1; i++) {
        if (goingUp) {
            int row = goingUp ? i : 0;
            int col = goingUp ? 0 : i;
            while (row >= 0 && row < m && col >= 0 && col < n) {
                result[index++] = mat[row][col];
                row--;
                col++;
            }
            if (col == n) {
                row += 2;
                col = n - 1;
            } else {
                row = 0;
            }
            goingUp = false;
        } else {
            int row = goingUp ? 0 : i;
            int col = goingUp ? i : 0;
            while (row >= 0 && row < m && col >= 0 && col < n) {
                result[index++] = mat[row][col];
                row++;
                col--;
            }
            if (row == m) {
                col += 2;
                row = m - 1;
            } else {
                col = 0;
            }
            goingUp = true;
        }
    }
    return result;
}

