    // Find the first digit that can be swapped to make the number smaller
    int i;
    for (i = len - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            break;
        }
    }

    // If no such digit is found, return -1
    if (i == -1) {
        return -1;
    }

    // Find the smallest digit on the right side of (i-th digit) which is greater than digits[i]
    int j;
    for (j = len - 1; j > i; j--) {
        if (digits[j] > digits[i]) {
            break;
        }
    }

    // Swap the found digits
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Sort the digits after the (i-th digit) in ascending order
    Arrays.sort(digits, i + 1, len);

    // Convert the digits back to number
    long val = Long.parseLong(new String(digits));
    return (val > Integer.MAX_VALUE) ? -1 : (int) val;
