public class SmallestIntegerFinder {

    /**
     * Finds the smallest integer that can be formed by rearranging the digits of the given positive integer n, which is greater than n.
     *
     * @param n The input positive integer.
     * @return The smallest rearranged integer greater than n, or -1 if not possible.
     */
    public static int findSmallestInteger(int n) {
        char[] digits = Integer.toString(n).toCharArray();

        // Find the first digit that can be swapped to make a larger number
        int i;
        for (i = digits.length - 2; i >= 0; i--) {
            if (digits[i] < digits[i + 1]) {
                break;
            }
        }

        // If no such digit is found, return -1 (no larger rearrangement possible)
        if (i == -1) {
            return -1;
        }

        // Find the smallest digit on the right side of (i) which is larger than digits[i]
        int j;
        for (j = digits.length - 1; j > i; j--) {
            if (digits[j] > digits[i]) {
                break;
            }
        }

        // Swap the found digits
        char temp = digits[i];
        digits[i] = digits[j];
        digits[j] = temp;

        // Sort the digits after the (i)th position
        Arrays.sort(digits, i + 1, digits.length);

        // Convert the char array back to an integer
        try {
            return Integer.parseInt(new String(digits));
        } catch (NumberFormatException e) {
            // Should never happen as the input is a valid integer
            return -1;
        }
    }

