import java.util.*;

public class SmallestIntegerFinder {

    /**
     * Finds the smallest integer greater than the given integer n by rearranging its digits.
     *
     * @param n The input positive integer.
     * @return The smallest rearranged integer greater than n, or -1 if not possible.
     */
    public static int findSmallestInteger(int n) {
        char[] digits = Integer.toString(n).toCharArray();
        int length = digits.length;

        // Traverse the digits from the second last to the first
        for (int i = length - 2; i >= 0; i--) {
            if (digits[i] < digits[i + 1]) {
                // Find the smallest digit on the right side of (i-th digit) but greater than digits[i]
                int minIndex = i + 1;
                for (int j = i + 2; j < length; j++) {
                    if (digits[j] > digits[i] && digits[j] < digits[minIndex]) {
                        minIndex = j;
                    }
                }

                // Swap the found digit with digits[i]
                char temp = digits[i];
                digits[i] = digits[minIndex];
                digits[minIndex] = temp;

                // Sort the digits after the (i-th digit) in ascending order
                Arrays.sort(digits, i + 1, length);
                return Integer.parseInt(new String(digits));
            }
        }

        // If no such digit is found, return -1
        return -1;
    }

    public static void main(String[] args) {
        System.out.println(findSmallestInteger(12)); // Output: 21
        System.out.println(findSmallestInteger(2071)); // Output: 2107
        System.out.println(findSmallestInteger(431)); // Output: -1
        System.out.println(findSmallestInteger(123456789)); // Output: 123456798
        System.out.println(findSmallestInteger(987654321)); // Output: -1
    }
