public class CenterSymmetricNumbers {

    /**
     * Generates all center symmetric numbers of length n.
     *
     * @param n The length of the center symmetric numbers.
     * @return A list of center symmetric numbers.
     */
    public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        helper(result, "", n, n);
        return result;
    }

    private static void helper(List<String> result, String partial, int left, int right) {
        if (left > right) {
            result.add(partial);
            return;
        }
        if (left == right) {
            if (partial.isEmpty()) {
                result.add("0");
            } else {
                result.add(partial + "0" + partial);
                result.add(partial + "1" + partial);
                result.add(partial + "8" + partial);
            }
            return;
        }
        if (left == 0) {
            result.add("1" + partial + "1");
            result.add("6" + partial + "9");
            result.add("8" + partial + "8");
            result.add("9" + partial + "6");
        } else {
            helper(result, "0" + partial + "0", left - 1, right - 1);
            helper(result, "1" + partial + "1", left - 1, right - 1);
            helper(result, "6" + partial + "9", left - 1, right - 1);
            helper(result, "8" + partial + "8", left - 1, right - 1);
            helper(result, "9" + partial + "6", left - 1, right - 1);
        }
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: [11,69,88,96]
        System.out.println(centerSymmetricNumbers(1)); // Output: [0,1,8]
    }
}
