import java.util.ArrayList;
import java.util.List;

public class CenterSymmetricNumbers {

    /**
     * Returns all center symmetric numbers of length n.
     *
     * @param n The length of the center symmetric numbers.
     * @return A list of center symmetric numbers.
     */
    public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n == 0) {
            return result;
        }
        if (n == 1) {
            result.add("0");
            result.add("1");
            result.add("8");
            return result;
        }
        char[] middle = {'0', '1', '8'};
        char[] asymmetric = {'6', '9'};
        backtrack(result, new char[n], 0, n - 1, middle, asymmetric);
        return result;
    }

    private static void backtrack(List<String> result, char[] current, int left, int right, char[] middle, char[] asymmetric) {
        if (left > right) {
            result.add(new String(current));
            return;
        }
        if (left == right) {
            for (char c : middle) {
                current[left] = c;
                result.add(new String(current));
            }
            if (asymmetric.length > 0) {
                current[left] = '0';
            }
            return;
        }
        for (char c : asymmetric) {
            current[left] = c;
            current[right] = getSymmetric(c);
            backtrack(result, current, left + 1, right - 1, middle, asymmetric);
        }
        if (asymmetric.length > 0) {
            current[left] = '0';
            current[right] = '0';
            backtrack(result, current, left + 1, right - 1, middle, asymmetric);
        }
    }

    private static char getSymmetric(char c) {
        if (c == '6') {
            return '9';
        } else if (c == '9') {
            return '6';
        } else {
            return c;
        }
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // ["11", "69", "88", "96"]
        System.out.println(centerSymmetricNumbers(1)); // ["0", "1", "8"]
    }
}
