import java.util.ArrayList;
import java.util.List;

public class CenterSymmetricNumbers {

    public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n == 1) {
            result.add("0");
            result.add("1");
            result.add("8");
            return result;
        }
        char[] options = {'0', '1', '6', '8', '9'};
        backtrack(result, new StringBuilder(), n, 0, n - 1, options);
        return result;
    }

    private static void backtrack(List<String> result, StringBuilder current, int n, int left, int right, char[] options) {
        if (left > right) {
            result.add(current.toString());
            return;
        }
        if (left == right) {
            for (char option : options) {
                if (option == '0' && current.length() == 0) continue;
                current.append(option);
                result.add(current.toString());
                current.deleteCharAt(current.length() - 1);
            }
            return;
        }
        if (left == n - 1 && right == 1) {
            for (char option : new char[]{'1', '8', '6', '9'}) {
                current.append(option);
                result.add(current.toString());
                current.deleteCharAt(current.length() - 1);
            }
            return;
        }
        for (int i = 0; i < options.length; i++) {
            char option = options[i];
            if (option == '0' && left == 0) continue;
            current.append(option);
            backtrack(result, current, n, left + 1, right - 1, options);
            current.deleteCharAt(current.length() - 1);
        }
    }
}
