public static int minPerfectSquareSum(int n) {
    if (n <= 3) {
        return n;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 1;
    dp[2] = 2;
    dp[3] = 3;
    for (int i = 4; i <= n; i++) {
        dp[i] = i;
        for (int j = 1; j <= i / 2; j++) {
            dp[i] = Math.min(dp[i], dp[j * j] + dp[i - j * j]);
        }
    }
    return dp[n];
}
